-- Três lotes. Envolver em BEGIN/COMMIT para carga conjunta atômica.
-- Etapa 39: Ciências; originais geradas com auxílio de IA, revisão humana pendente.
-- Gerado por scripts/build-subject-content.mjs. Uma instrução atômica por lote.
-- Fonte atual: revisão da etapa 41, versão 2; INSERT não atualiza linhas existentes.
-- Conflitos de ID preservam conteúdo/modelos/gabaritos; sem reparo silencioso.
with source_data (id, statement, option_a, option_b, option_c, option_d, option_e,
                  topic, difficulty, correct_answer, explanation) as (
  values
  ('d1390000-0000-4000-8000-000000000001', 'Na fotossíntese realizada por uma planta verde, qual é a principal fonte de energia usada para produzir matéria orgânica?', 'A matéria orgânica pronta das raízes', 'O calor liberado pelos animais', 'O sal da água', 'O oxigênio do solo', 'A luz do Sol', 'Fotossíntese', 'easy', 'E', 'A planta utiliza energia luminosa para produzir matéria orgânica a partir de substâncias como água e dióxido de carbono. A luz é fonte de energia, não um nutriente retirado do solo.'),
  ('d1390000-0000-4000-8000-000000000002', 'Em uma célula de folha de uma planta verde, qual organela está diretamente relacionada à realização da fotossíntese?', 'Cloroplasto', 'Núcleo', 'Lisossomo', 'Mitocôndria', 'Ribossomo', 'Cloroplastos', 'medium', 'A', 'Em plantas, a fotossíntese ocorre nos cloroplastos, que contêm pigmentos capazes de captar luz. A mitocôndria participa de processos da respiração celular.'),
  ('d1390000-0000-4000-8000-000000000003', 'Folhas caídas em uma floresta são degradadas por fungos e bactérias decompositoras. Qual é a importância desse processo para o ambiente?', 'Impedir qualquer crescimento de plantas', 'Devolver nutrientes à circulação no ecossistema', 'Transformar toda a matéria em luz', 'Eliminar definitivamente os elementos químicos', 'Parar a circulação de água', 'Decomposição', 'easy', 'B', 'A decomposição transforma a matéria orgânica e contribui para devolver nutrientes ao ambiente. Ela participa da ciclagem da matéria, sem fazer os elementos químicos desaparecerem.'),
  ('d1390000-0000-4000-8000-000000000004', 'Nas células animais, qual organela participa de etapas da respiração celular aeróbia associadas à produção de ATP?', 'Cromossomo', 'Vacúolo central vegetal', 'Mitocôndria', 'Cloroplasto', 'Parede celular', 'Respiração celular', 'medium', 'C', 'A mitocôndria participa de etapas da respiração celular aeróbia que produzem ATP, uma molécula usada nas atividades celulares. Nem todas as etapas da respiração ocorrem dentro dessa organela.'),
  ('d1390000-0000-4000-8000-000000000005', 'Uma célula precisa trocar substâncias com seu meio e controlar parte do que entra e sai. Qual estrutura atua como esse limite seletivo da célula?', 'Membrana plasmática', 'Ribossomo', 'Nucléolo', 'Cromossomo', 'Centríolo', 'Membrana celular', 'easy', 'A', 'A membrana plasmática delimita a célula e apresenta permeabilidade seletiva. Ela participa do controle das trocas de substâncias entre o interior celular e o ambiente.'),
  ('d1390000-0000-4000-8000-000000000006', 'Considere a cadeia: algas → pequenos crustáceos → peixes → garças. As setas apontam do alimento para quem o consome. Qual componente é consumidor secundário nessa cadeia?', 'Algas', 'Peixes', 'Garças', 'Pequenos crustáceos', 'Todos os componentes', 'Níveis tróficos', 'medium', 'B', 'Os crustáceos consomem as algas produtoras e são consumidores primários. Os peixes que comem esses crustáceos são consumidores secundários. As garças ocupam o nível seguinte na cadeia apresentada.'),
  ('d1390000-0000-4000-8000-000000000007', 'Uma pequena poça diminui ao longo de uma tarde sem chuva, sem escoar e sem infiltrar no solo. A água passa gradualmente para a atmosfera. Qual processo explica essa passagem?', 'Fusão', 'Precipitação', 'Condensação', 'Solidificação', 'Evaporação', 'Evaporação', 'easy', 'E', 'Na evaporação, a água líquida passa ao estado gasoso. Esse processo pode acontecer na superfície da água sem que ela esteja fervendo.'),
  ('d1390000-0000-4000-8000-000000000008', 'Gotas aparecem na parte externa de um copo fechado com água gelada, colocado em ambiente úmido. Considerando que o copo não vaza, de onde vêm essas gotas?', 'Da criação de água sem matéria anterior', 'Do vidro, que se transforma em água', 'Do sal dissolvido que sai do copo', 'Do vapor de água do ar que se condensa', 'Do gelo que atravessa o vidro', 'Condensação', 'easy', 'D', 'O vapor de água presente no ar perde energia ao entrar em contato com a superfície fria e passa ao estado líquido. Essa condensação forma as gotas externas.'),
  ('d1390000-0000-4000-8000-000000000009', 'Uma mistura contém água e areia insolúvel, cujos grãos são maiores que os poros de um filtro. Qual procedimento pode reter a areia e deixar a água atravessar?', 'Filtração', 'Dissolução completa da areia', 'Fusão do recipiente', 'Magnetização da água', 'Congelamento sem separação', 'Separação de misturas', 'easy', 'A', 'O filtro retém os grãos sólidos maiores que seus poros, enquanto a água atravessa. A filtração separa, nesse caso, um sólido insolúvel de um líquido; não torna a água necessariamente potável.'),
  ('d1390000-0000-4000-8000-000000000010', 'Uma pequena quantidade de sal se dissolve completamente em água, formando uma mistura uniforme. Nessa solução, como o sal é classificado?', 'Precipitado sólido presente', 'Filtro', 'Recipiente', 'Soluto', 'Solvente', 'Soluções', 'easy', 'D', 'O sal é o soluto, isto é, a substância dissolvida. A água atua como solvente. A dissolução completa nas condições descritas resulta em uma solução uniforme.'),
  ('d1390000-0000-4000-8000-000000000011', 'Um bloco homogêneo tem massa de 200 g e volume de 100 cm³. Usando densidade = massa ÷ volume, qual é sua densidade?', '100 g/cm³', '20 g/cm³', '0,5 g/cm³', '300 g/cm³', '2 g/cm³', 'Densidade', 'medium', 'E', 'A densidade é 200 ÷ 100 = 2 g/cm³. A unidade relaciona a massa em gramas ao volume em centímetros cúbicos.'),
  ('d1390000-0000-4000-8000-000000000012', 'Uma força resultante de 20 N atua sobre um carrinho de massa 4 kg. Usando F = m × a, qual é a aceleração do carrinho?', '5 m/s²', '16 m/s²', '80 m/s²', '0,2 m/s²', '4 m/s²', 'Força e aceleração', 'medium', 'A', 'Pela relação fornecida, a = F ÷ m = 20 ÷ 4 = 5 m/s². O valor usado é o da força resultante, que já reúne as forças que atuam no carrinho.'),
  ('d1390000-0000-4000-8000-000000000013', 'Um veículo percorre 24 km em 2 horas. Qual é sua velocidade média, considerando todo esse intervalo?', '48 km/h', '22 km/h', '6 km/h', '12 km/h', '26 km/h', 'Velocidade média', 'medium', 'D', 'A velocidade média é a distância percorrida dividida pelo tempo total: 24 ÷ 2 = 12 km/h. Isso não exige que a velocidade tenha sido constante durante o percurso.'),
  ('d1390000-0000-4000-8000-000000000014', 'Uma ponta de uma colher de metal fica em contato com um líquido quente. Depois de algum tempo, a outra ponta também aquece. Qual mecanismo explica principalmente a transferência de energia ao longo do metal?', 'Convecção térmica', 'Condução térmica', 'Radiação térmica', 'Dilatação térmica', 'Evaporação do líquido', 'Condução térmica', 'medium', 'B', 'A condução transfere energia térmica através do material, da região mais quente para a mais fria, sem exigir deslocamento do metal como um todo.'),
  ('d1390000-0000-4000-8000-000000000015', 'Um circuito simples tem pilha carregada, fios, lâmpada compatível e interruptor, todos em bom estado. O interruptor aberto interrompe o caminho elétrico. O que deve ocorrer para a lâmpada acender nesse circuito?', 'Cortar outro fio', 'Separar os dois terminais da lâmpada dos fios', 'Retirar a pilha', 'Retirar a lâmpada do circuito', 'Fechar o interruptor e completar o caminho elétrico', 'Circuito elétrico simples', 'medium', 'E', 'Um caminho elétrico completo permite a circulação de corrente no circuito descrito. Fechar o interruptor restabelece esse caminho; abrir ou cortar conexões o interrompe.'),
  ('d1390000-0000-4000-8000-000000000016', 'Ao observar a Lua iluminada no céu, qual é a principal origem da luz que vemos em sua superfície?', 'Luz produzida pela sombra da Terra', 'Luz produzida por combustão na Lua', 'Luz gerada pelo som na atmosfera terrestre', 'Luz do Sol refletida pela Lua', 'Luz emitida por oceanos lunares', 'Luz da Lua', 'easy', 'D', 'A Lua não produz luz visível como uma estrela. Sua superfície reflete parte da luz solar, e a porção iluminada que observamos varia conforme a posição relativa entre Sol, Terra e Lua.'),
  ('d1390000-0000-4000-8000-000000000017', 'Qual combinação explica principalmente as estações do ano na Terra?', 'As fases da Lua e a duração do ciclo lunar', 'A variação da distância entre a Terra e o Sol ao longo da órbita', 'A inclinação do eixo terrestre e a translação ao redor do Sol', 'A variação da atividade solar ao longo de seu ciclo', 'A rotação da Terra ao longo de cada dia', 'Estações do ano', 'medium', 'C', 'Com o eixo inclinado, a translação faz variar a incidência de luz e a duração dos dias em cada hemisfério ao longo do ano. A causa principal não é simplesmente a Terra estar mais perto ou mais longe do Sol.'),
  ('d1390000-0000-4000-8000-000000000018', 'Uma turma quer investigar o efeito da quantidade de água no crescimento de plantas. Usa plantas semelhantes, vasos e solo iguais. Qual planejamento permite comparar principalmente o efeito da água?', 'Variar água, luz e tipo de solo ao mesmo tempo', 'Trocar a espécie de planta em cada quantidade de água', 'Mudar o solo e manter a quantidade de água igual', 'Colocar cada vaso em uma temperatura diferente', 'Variar a água e manter semelhantes as demais condições', 'Controle de variáveis', 'medium', 'E', 'Variar a quantidade de água e manter as demais condições semelhantes reduz a influência de outros fatores na comparação. Repetições e registros também ajudam; um único resultado não prova uma regra universal.')
), inserted_model as (
  insert into private.simulations(id,title,question_count,subject,published,free_access)
  values('d1391000-0000-4000-8000-000000000001','Ciências',20,'ciencias',false,false)
  on conflict(id) do nothing returning id
), inserted_questions as (
  insert into public.questions(id,statement,option_a,option_b,option_c,option_d,option_e,
                               subject,topic,difficulty,target_exam,status,version)
  select id::uuid,statement,option_a,option_b,option_c,option_d,option_e,
         'ciencias',topic,difficulty,'both','draft',2 from source_data
  on conflict(id) do nothing returning id
)
insert into public.question_answers(question_id,correct_answer,explanation)
select q.id,s.correct_answer,s.explanation
from inserted_questions q join source_data s on s.id::uuid=q.id;

-- Etapa 39: História; originais geradas com auxílio de IA, revisão humana pendente.
-- Gerado por scripts/build-subject-content.mjs. Uma instrução atômica por lote.
-- Fonte atual: revisão da etapa 41, versão 2; INSERT não atualiza linhas existentes.
-- Conflitos de ID preservam conteúdo/modelos/gabaritos; sem reparo silencioso.
with source_data (id, statement, option_a, option_b, option_c, option_d, option_e,
                  topic, difficulty, correct_answer, explanation) as (
  values
  ('d1392000-0000-4000-8000-000000000001', 'Em uma pesquisa sobre a história de um bairro, estudantes gravam entrevistas com antigos moradores. Que tipo de fonte é produzido principalmente por essas entrevistas?', 'Fonte oral', 'Fonte cartográfica', 'Fonte mineral', 'Fonte arqueológica sem linguagem', 'Fonte exclusivamente numérica', 'Fontes orais', 'easy', 'A', 'Entrevistas registram relatos falados e constituem fontes orais. Esses relatos apresentam memórias e perspectivas que devem ser contextualizadas e comparadas com outros registros.'),
  ('d1392000-0000-4000-8000-000000000002', 'Em um exercício hipotético, uma fotografia de uma praça mostra poucas pessoas em certo instante de 1930. Qual conclusão é adequada para uma análise histórica dessa imagem?', 'Ninguém morava na cidade naquele ano.', 'A fotografia registra todos os acontecimentos de 1930.', 'Nenhuma fotografia pode ser usada como fonte.', 'A imagem mostra um recorte que deve ser relacionado a outras fontes.', 'Todas as praças do país eram iguais.', 'Leitura de fotografias', 'medium', 'D', 'Uma fotografia registra um recorte de tempo e espaço, com enquadramento e condições de produção. Ela é uma fonte útil, mas não representa automaticamente toda a cidade ou todo o ano.'),
  ('d1392000-0000-4000-8000-000000000003', 'Dois jornais de uma mesma época descrevem um conflito de maneiras diferentes. Qual procedimento ajuda a investigar historicamente essa diferença?', 'Aceitar sempre o jornal com mais páginas.', 'Examinar autoria, público, contexto e outras evidências.', 'Supor que nenhum jornal tem posição editorial.', 'Escolher a versão mais agradável ao pesquisador.', 'Descartar ambos apenas por discordarem.', 'Crítica das fontes', 'medium', 'B', 'A análise considera quem produziu cada relato, para qual público e em quais circunstâncias, além da comparação com outras fontes. A discordância pode revelar perspectivas e interesses distintos.'),
  ('d1392000-0000-4000-8000-000000000004', 'Na contagem convencional dos séculos da era comum, a que século pertence o ano de 1750?', 'Século XVIII', 'Século XX', 'Século XIX', 'Século XVII', 'Século XVI', 'Séculos', 'easy', 'A', 'O século XVIII corresponde aos anos de 1701 a 1800. Como 1750 está nesse intervalo, pertence ao século XVIII.'),
  ('d1392000-0000-4000-8000-000000000005', 'Considere os marcos e anos: I. Proclamação da República, 1889. II. Abertura dos portos às nações amigas, 1808. III. Lei Áurea, 1888. Qual ordem apresenta os marcos do mais antigo ao mais recente?', 'I – II – III', 'I – III – II', 'III – I – II', 'II – I – III', 'II – III – I', 'Ordenação cronológica', 'easy', 'E', 'Ordenando os anos em ordem crescente, temos 1808, 1888 e 1889. Portanto, a sequência é abertura dos portos, Lei Áurea e Proclamação da República: II, III e I.'),
  ('d1392000-0000-4000-8000-000000000006', 'A abertura dos portos às nações amigas, em 1808, alterou uma regra importante do comércio colonial. Qual mudança está relacionada a essa medida?', 'Criação da República brasileira.', 'Proibição de qualquer comércio marítimo.', 'Abolição imediata da escravidão em todo o Brasil.', 'Permissão de comércio com nações amigas de Portugal.', 'Proibição de entrada da corte portuguesa no Brasil.', 'Abertura dos portos', 'medium', 'D', 'A medida permitiu comércio com nações amigas de Portugal e rompeu a exclusividade comercial metropolitana. Não significou abolição da escravidão ou implantação de uma república.'),
  ('d1392000-0000-4000-8000-000000000007', 'Qual acontecimento ajuda a explicar o contexto da transferência da corte portuguesa para o Brasil em 1808?', 'A Revolução Pernambucana e seus conflitos com a monarquia.', 'A Revolução Liberal do Porto e a reivindicação do retorno da corte.', 'A elevação do Brasil à condição de Reino Unido a Portugal e Algarves.', 'A independência do Brasil e a formação do Primeiro Reinado.', 'As guerras napoleônicas e a invasão de Portugal.', 'Transferência da corte', 'medium', 'E', 'A ameaça e a invasão de Portugal no contexto das guerras napoleônicas contribuíram para a transferência da corte. A elevação a Reino Unido ocorreu em 1815; a Revolução Pernambucana, em 1817; a Revolução Liberal do Porto, em 1820; e a independência e o Primeiro Reinado pertencem ao período iniciado em 1822. Esses acontecimentos posteriores não explicam a transferência em 1808.'),
  ('d1392000-0000-4000-8000-000000000008', 'Qual foi a determinação central da Lei Áurea, de 13 de maio de 1888?', 'Transferir a capital para Brasília.', 'Proibir a entrada de qualquer mercadoria estrangeira.', 'Instituir o voto universal.', 'Extinguir legalmente a escravidão no Brasil.', 'Criar o regime republicano.', 'Abolição legal da escravidão', 'easy', 'D', 'A Lei Áurea determinou a extinção da escravidão no Brasil. Esse conteúdo legal não deve ser confundido com a eliminação imediata de todas as desigualdades ou com a criação da República.'),
  ('d1392000-0000-4000-8000-000000000009', 'A Lei do Ventre Livre, de 1871, declarou de condição livre os filhos de mulheres escravizadas nascidos a partir de sua data. Qual afirmação interpreta essa medida sem ampliar indevidamente seu alcance?', 'A lei criou a República brasileira.', 'A medida concedeu terra a toda pessoa nascida antes de 1871.', 'A regra sobre os nascimentos não libertava automaticamente todas as pessoas adultas escravizadas.', 'Toda a escravidão brasileira terminou imediatamente em 1871.', 'A lei passou a proibir todos os nascimentos no país.', 'Lei do Ventre Livre', 'medium', 'C', 'A disposição sobre os filhos nascidos a partir da lei não equivalia à abolição geral. A própria lei estabelecia condições de criação e de utilização de serviços desses menores, limitando a liberdade prática.'),
  ('d1392000-0000-4000-8000-000000000010', 'Qual transformação política está associada à Proclamação da República no Brasil, em 15 de novembro de 1889?', 'Abolição da escravidão pela Lei do Ventre Livre.', 'Fim da monarquia e implantação de um regime republicano.', 'Transferência da corte portuguesa para o Brasil.', 'Retorno do Brasil à condição de colônia portuguesa.', 'Criação do primeiro governo monárquico brasileiro.', 'Proclamação da República', 'easy', 'B', 'A Proclamação da República encerrou a monarquia e foi seguida por um governo provisório republicano. Essa mudança de regime não significou participação eleitoral de toda a população.'),
  ('d1392000-0000-4000-8000-000000000011', 'Segundo o artigo 70 da Constituição brasileira de 1891, os analfabetos não podiam se alistar como eleitores. O que essa restrição permite concluir sobre aquele sistema eleitoral?', 'Não existia qualquer regra de alistamento.', 'Somente crianças eram eleitores.', 'A restrição referia-se apenas a visitantes estrangeiros.', 'Todos os habitantes tinham acesso ao voto.', 'A participação eleitoral possuía exclusões legais.', 'Limites do voto em 1891', 'medium', 'E', 'A exclusão dos analfabetos mostra que a participação eleitoral não abrangia toda a população. A questão trata da regra histórica de 1891, e não das regras eleitorais atuais.'),
  ('d1392000-0000-4000-8000-000000000012', 'Nos artigos iniciais da Constituição de 1891, as antigas províncias passam a formar estados unidos em uma República Federativa. Que organização política está indicada nessa estrutura?', 'A união de estados em uma federação.', 'A transformação de cada estado em colônia estrangeira.', 'A criação de uma única cidade sem divisões territoriais.', 'O retorno ao regime de capitanias hereditárias.', 'A extinção de qualquer governo nacional.', 'Federalismo na Constituição de 1891', 'medium', 'A', 'A federação reúne estados em uma organização nacional. Os artigos 1º e 2º da Constituição de 1891 expressam a união e a transformação das antigas províncias em estados.'),
  ('d1392000-0000-4000-8000-000000000013', 'No contexto da Revolução Francesa, o artigo 1º da Declaração dos Direitos do Homem e do Cidadão, de 1789, apresenta qual princípio?', 'Submissão de todo cidadão a um senhor feudal.', 'Obrigatoriedade de uma única profissão para todos.', 'Privilégios jurídicos determinados exclusivamente pelo nascimento.', 'Proibição de expressar qualquer opinião.', 'Liberdade e igualdade em direitos.', 'Declaração de direitos de 1789', 'medium', 'E', 'O artigo afirma a liberdade e a igualdade em direitos. Enunciar esse princípio não comprova que ele tenha sido aplicado imediatamente a todas as pessoas ou em todas as situações.'),
  ('d1392000-0000-4000-8000-000000000014', 'Uma tabuleta cuneiforme da antiga Mesopotâmia registra a distribuição de utensílios de cobre. O que esse uso da escrita permite compreender?', 'Utensílios de cobre eram inventados no século XX.', 'Todos os habitantes sabiam ler necessariamente.', 'A escrita também podia registrar a circulação e a administração de bens.', 'Não existia qualquer controle de bens.', 'A escrita servia exclusivamente para poesias.', 'Escrita e administração na Mesopotâmia', 'medium', 'C', 'Registros de distribuição de bens mostram usos administrativos e econômicos da escrita. A existência de uma tabuleta não implica alfabetização de toda a população.'),
  ('d1392000-0000-4000-8000-000000000015', 'Em um exemplo didático de organização fabril, um grupo corta o tecido, outro costura e um terceiro embala as peças. Qual característica da produção é descrita?', 'Ausência de qualquer organização do trabalho.', 'Cada trabalhador produz sozinho todas as peças do início ao fim.', 'Divisão de tarefas entre trabalhadores.', 'Produção de alimentos por coleta silvestre.', 'Fim de todas as etapas de fabricação.', 'Divisão de tarefas na produção', 'easy', 'C', 'As etapas são distribuídas entre grupos, caracterizando divisão de tarefas. O exemplo não afirma que toda fábrica tenha exatamente essa organização ou que cada trabalhador realize o processo completo.'),
  ('d1392000-0000-4000-8000-000000000016', 'Ao estudar a história dos povos indígenas no Brasil, qual abordagem evita tratá-los como um único grupo cultural?', 'Supor que todos vivem de modo idêntico em qualquer lugar.', 'Considerar que suas histórias começaram apenas com registros europeus.', 'Afirmar que todos sempre falaram a mesma língua.', 'Negar a existência de mudanças históricas entre esses povos.', 'Reconhecer diferentes povos, línguas e formas de organização.', 'Diversidade dos povos indígenas', 'easy', 'E', 'Existem diversos povos indígenas, com línguas, trajetórias e formas de organização próprias. Estudar essa diversidade evita generalizações e reconhece seus sujeitos e processos históricos.'),
  ('d1392000-0000-4000-8000-000000000017', 'Em uma comparação hipotética, fotografias de 1950 e 2020 mostram a mesma estação ferroviária: o edifício permanece, mas a praça ao redor passou a ter novas vias. Qual leitura histórica considera as duas observações?', 'Nada mudou entre as duas datas.', 'As fotografias demonstram que os dois anos são o mesmo momento.', 'Nenhum elemento permaneceu.', 'Há permanência do edifício e transformação de parte de seu entorno.', 'A imagem de 2020 prova como a praça era em todos os séculos.', 'Mudanças e permanências', 'medium', 'D', 'A comparação identifica um elemento que permanece e outro que se transforma. Mudanças e permanências podem coexistir; os registros não mostram todos os acontecimentos do intervalo.'),
  ('d1392000-0000-4000-8000-000000000018', 'Qual exemplo se relaciona principalmente à dimensão imaterial do patrimônio cultural?', 'As paredes físicas de um edifício.', 'A massa de uma pedra sem relação com uma prática cultural.', 'O concreto de uma ponte.', 'Saberes e modos de fazer transmitidos por uma comunidade.', 'Um terreno considerado apenas por sua área em metros quadrados.', 'Patrimônio cultural imaterial', 'medium', 'D', 'Saberes, modos de fazer e práticas transmitidas por comunidades integram a dimensão imaterial do patrimônio. Isso não significa que toda prática esteja automaticamente registrada como bem cultural oficial.')
), inserted_model as (
  insert into private.simulations(id,title,question_count,subject,published,free_access)
  values('d1393000-0000-4000-8000-000000000001','História',20,'historia',false,false)
  on conflict(id) do nothing returning id
), inserted_questions as (
  insert into public.questions(id,statement,option_a,option_b,option_c,option_d,option_e,
                               subject,topic,difficulty,target_exam,status,version)
  select id::uuid,statement,option_a,option_b,option_c,option_d,option_e,
         'historia',topic,difficulty,'both','draft',2 from source_data
  on conflict(id) do nothing returning id
)
insert into public.question_answers(question_id,correct_answer,explanation)
select q.id,s.correct_answer,s.explanation
from inserted_questions q join source_data s on s.id::uuid=q.id;

-- Etapa 39: Geografia; originais geradas com auxílio de IA, revisão humana pendente.
