-- Conflitos de ID preservam conteúdo/modelos/gabaritos; sem reparo silencioso.
with source_data (id, statement, option_a, option_b, option_c, option_d, option_e,
                  topic, difficulty, correct_answer, explanation) as (
  values
  ('d1394000-0000-4000-8000-000000000001', 'Um ponto está localizado a 15° de latitude sul e 45° de longitude oeste. Em quais hemisférios ele se encontra?', 'Norte e Leste', 'Norte e Sul simultaneamente', 'Sul e Leste', 'Norte e Oeste', 'Sul e Oeste', 'Coordenadas e hemisférios', 'easy', 'E', 'A latitude sul indica posição ao sul da linha do Equador. A longitude oeste indica posição a oeste do meridiano de Greenwich. Portanto, o ponto fica nos hemisférios Sul e Oeste.'),
  ('d1394000-0000-4000-8000-000000000002', 'No sistema usual de coordenadas geográficas, as longitudes são medidas para leste ou oeste a partir de qual referência de 0°?', 'Trópico de Capricórnio', 'Linha do Equador', 'Meridiano de Greenwich', 'Círculo Polar Antártico', 'Trópico de Câncer', 'Meridiano de referência', 'easy', 'C', 'O meridiano de Greenwich é a referência de longitude 0°. A linha do Equador é a referência para latitude, e não para longitude.'),
  ('d1394000-0000-4000-8000-000000000003', 'Em um modelo simplificado de fusos horários, cada 15° de longitude corresponde a uma hora, com horários mais adiantados a leste. Se são 10h no meridiano de 0°, que horas são no meridiano de 30° leste nesse modelo?', '14h', '12h', '10h', '8h', '11h', 'Fusos teóricos', 'medium', 'B', 'A diferença é de 30 ÷ 15 = 2 horas. Como o ponto está a leste, somam-se duas horas: 12h. O exercício usa fusos teóricos, sem fronteiras oficiais ou horário de verão.'),
  ('d1394000-0000-4000-8000-000000000004', 'Em um mapa fictício de uso do solo, a legenda indica verde para floresta, amarelo para agricultura e cinza para área construída. O que representa uma área amarela nesse mapa?', 'Uma fronteira internacional necessariamente', 'Agricultura', 'Área construída', 'Um rio necessariamente', 'Floresta', 'Legenda cartográfica', 'easy', 'B', 'A legenda fornecida associa amarelo à agricultura. Cores e símbolos precisam ser interpretados pela legenda do mapa específico, sem supor que tenham sempre o mesmo significado em todos os mapas.'),
  ('d1394000-0000-4000-8000-000000000005', 'Um mapa representa curvas de nível, cada uma ligando pontos de mesma altitude, com intervalo de 20 m entre curvas consecutivas. Na mesma escala, em qual trecho a encosta tende a ser mais íngreme?', 'Onde as curvas estão mais afastadas.', 'Onde não existe mudança de altitude.', 'Em qualquer trecho, pois a distância entre as curvas não importa.', 'Onde as curvas estão mais próximas.', 'Onde todas as curvas têm exatamente a mesma altitude.', 'Curvas de nível', 'medium', 'D', 'Com intervalo de altitude e escala iguais, curvas próximas indicam a mesma variação vertical em menor distância horizontal. Isso corresponde a maior declividade da encosta.'),
  ('d1394000-0000-4000-8000-000000000006', 'Em um mapa de escala 1:50.000, a distância em linha reta entre dois pontos mede 4 cm. Qual é a distância real correspondente?', '200 m', '20 m', '20 km', '200 km', '2 km', 'Escala e conversão de distância', 'medium', 'E', 'A distância real é 4 × 50.000 = 200.000 cm. Como 100.000 cm correspondem a 1 km, o resultado é 2 km.'),
  ('d1394000-0000-4000-8000-000000000007', 'Um município fictício tem 90.000 habitantes distribuídos em uma área de 300 km². Usando densidade demográfica = população ÷ área, qual é sua densidade média?', '300 hab./km²', '900 hab./km²', '3.000 hab./km²', '3 hab./km²', '30 hab./km²', 'Densidade demográfica', 'medium', 'A', 'Dividindo 90.000 habitantes por 300 km², obtemos 300 hab./km². É uma média do território e não significa que cada quilômetro quadrado tenha exatamente esse número de moradores.'),
  ('d1394000-0000-4000-8000-000000000008', 'Em uma região fictícia, a proporção da população residente em áreas urbanas passou de 60% para 80% entre duas pesquisas. Qual foi o aumento, em pontos percentuais?', '33 pontos percentuais', '140 pontos percentuais', '80 pontos percentuais', '20 pontos percentuais', '60 pontos percentuais', 'Proporção da população urbana', 'medium', 'D', 'A diferença entre as proporções é 80 − 60 = 20 pontos percentuais. Esse indicador não é o mesmo que o aumento percentual relativo de aproximadamente 33,3% sobre o valor inicial.'),
  ('d1394000-0000-4000-8000-000000000009', 'Uma família muda permanentemente de uma área rural para uma cidade em busca de trabalho. Qual tipo de deslocamento está exemplificado?', 'Migração pendular diária', 'Viagem de retorno no mesmo dia', 'Êxodo rural', 'Deslocamento de um bairro urbano para outro', 'Turismo de férias', 'Êxodo rural', 'easy', 'C', 'O êxodo rural é o deslocamento de pessoas do campo para a cidade. No exemplo, há mudança de residência, e não apenas uma viagem diária ou temporária.'),
  ('d1394000-0000-4000-8000-000000000010', 'Uma pessoa mora em um município, vai diariamente a outro para trabalhar e retorna à sua residência ao fim do dia. Como esse movimento é geralmente denominado?', 'Êxodo rural necessariamente', 'Mudança definitiva de país', 'Emigração permanente', 'Deslocamento pendular', 'Turismo internacional', 'Deslocamento pendular', 'easy', 'D', 'O deslocamento pendular envolve trajetos regulares de ida e volta, como os realizados para trabalhar ou estudar. A pessoa mantém sua residência, sem mudança definitiva no exemplo.'),
  ('d1394000-0000-4000-8000-000000000011', 'Uma indústria transforma algodão em tecido. Na divisão tradicional da economia em setores primário, secundário e terciário, essa atividade industrial pertence a qual setor?', 'Terciário, por prestar exclusivamente serviços de transporte.', 'Secundário, por transformar matéria-prima.', 'Primário, por extrair tecido pronto da natureza.', 'Primário, por envolver qualquer produto de origem vegetal.', 'Terciário, por ser necessariamente comércio varejista.', 'Setores da economia', 'easy', 'B', 'A transformação industrial da matéria-prima em tecido pertence ao setor secundário. O cultivo do algodão pertence ao primário; a venda e o transporte são exemplos de atividades do terciário.'),
  ('d1394000-0000-4000-8000-000000000012', 'Uma área de solo exposto e vegetação é coberta por asfalto impermeável. Mantidas as demais condições, qual efeito tende a ocorrer durante uma chuva?', 'Toda a água deixa de circular no ambiente.', 'A infiltração no trecho diminui e o escoamento superficial tende a aumentar.', 'A água desaparece sem escoar ou evaporar.', 'A chuva se transforma diretamente em neve.', 'A água passa a infiltrar mais facilmente pelo asfalto.', 'Impermeabilização e escoamento', 'medium', 'B', 'Superfícies impermeáveis dificultam a entrada da água no solo e favorecem o escoamento superficial. A intensidade do efeito também depende de chuva, relevo e drenagem.'),
  ('d1394000-0000-4000-8000-000000000013', 'Como se denomina a área cujas águas superficiais são drenadas por um rio principal e seus afluentes para uma saída comum?', 'Bacia hidrográfica', 'Limite de uma região política necessariamente', 'Fuso horário', 'Meridiano', 'Paralelo', 'Bacia hidrográfica', 'medium', 'A', 'Uma bacia hidrográfica é uma área de drenagem integrada por um rio e seus afluentes. Seus limites acompanham divisores de águas e não precisam coincidir com fronteiras políticas.'),
  ('d1394000-0000-4000-8000-000000000014', 'Uma notícia informa que choveu em uma cidade na manhã de terça-feira. Essa informação, sozinha, descreve principalmente:', 'a quantidade total de rios da região', 'a latitude exata da cidade', 'o clima completo da cidade durante vários séculos', 'uma condição do tempo atmosférico naquele momento', 'o bioma de todo o país', 'Tempo atmosférico e clima', 'medium', 'D', 'O tempo atmosférico corresponde às condições observadas em um momento ou intervalo curto. O clima se refere a padrões e variabilidade analisados ao longo de períodos extensos; uma manhã não é suficiente para caracterizá-lo.'),
  ('d1394000-0000-4000-8000-000000000015', 'Qual bioma brasileiro é associado ao semiárido e apresenta vegetação com diversas adaptações a períodos de pouca disponibilidade de água?', 'Floresta amazônica', 'Caatinga', 'Floresta temperada europeia', 'Manguezal exclusivamente', 'Pampa', 'Caatinga', 'easy', 'B', 'A Caatinga está associada ao semiárido brasileiro. Sua vegetação apresenta diferentes adaptações às condições de disponibilidade de água, sem que todas as plantas tenham exatamente a mesma estratégia.'),
  ('d1394000-0000-4000-8000-000000000016', 'Qual bioma brasileiro, restrito ao Rio Grande do Sul, apresenta extensas formações campestres?', 'Pantanal', 'Pampa', 'Amazônia', 'Caatinga', 'Cerrado', 'Pampa', 'easy', 'B', 'O Pampa brasileiro situa-se no Rio Grande do Sul e possui formações campestres características. Campos não são necessariamente áreas sem biodiversidade ou sem relevância ambiental.'),
  ('d1394000-0000-4000-8000-000000000017', 'Considerando renovável uma fonte reposta por processos naturais em escala compatível com seu uso, qual opção é uma fonte renovável de energia?', 'Vento usado na geração eólica', 'Carvão mineral', 'Gás natural fóssil', 'Urânio extraído de jazidas', 'Petróleo', 'Fontes renováveis de energia', 'easy', 'A', 'O vento é reposto por processos atmosféricos e pode ser utilizado na geração eólica. Ser renovável não significa produzir energia continuamente nem ter impacto ambiental inexistente.'),
  ('d1394000-0000-4000-8000-000000000018', 'Um mapa apresenta a distribuição da quantidade média de chuva por áreas de uma região, usando cores e uma legenda com valores. Qual é sua finalidade principal?', 'Representar necessariamente somente fronteiras internacionais.', 'Comprovar que todas as áreas recebem a mesma quantidade de chuva.', 'Mostrar apenas nomes de governantes.', 'Substituir toda observação meteorológica futura.', 'Representar espacialmente um fenômeno específico: a distribuição da chuva.', 'Mapas temáticos', 'easy', 'E', 'Um mapa temático destaca a distribuição espacial de um fenômeno selecionado. Nesse caso, cores e legenda permitem comparar quantidades de chuva entre áreas, conforme os dados usados no mapa.')
), inserted_model as (
  insert into private.simulations(id,title,question_count,subject,published,free_access)
  values('d1395000-0000-4000-8000-000000000001','Geografia',20,'geografia',false,false)
  on conflict(id) do nothing returning id
), inserted_questions as (
  insert into public.questions(id,statement,option_a,option_b,option_c,option_d,option_e,
                               subject,topic,difficulty,target_exam,status,version)
  select id::uuid,statement,option_a,option_b,option_c,option_d,option_e,
         'geografia',topic,difficulty,'both','draft',2 from source_data
  on conflict(id) do nothing returning id
)
insert into public.question_answers(question_id,correct_answer,explanation)
select q.id,s.correct_answer,s.explanation
from inserted_questions q join source_data s on s.id::uuid=q.id;
